class Solution {
public:
    uint32_t reverseBits(uint32_t n) {
        uint32_t res = 0;
        for (int i = 0; i < 32; ++i) {
            res = (res << 1) | (n & 1);
            n >>= 1;
        }
        return res;
    }
};

class Solution {
    public int reverseBits(int n) {
        int res = 0;
        for (int i = 0; i < 32; i++) {
            res = (res << 1) | (n & 1);
            n >>>= 1;
        }
        return res;
    }
}

var reverseBits = function(n) {
    let res = 0;
    for (let i = 0; i < 32; i++) {
        res = ((res << 1) | (n & 1)) >>> 0;
        n >>>= 1;
    }
    return res;
};
